import React, { useContext } from 'react';
import './CSS/ShopCategory.css';
import { ShopContext } from '../Context/ShopContext';
import Item from '../Components/Items/Item';

const ShopCategory = (props) => {
  const { all_product } = useContext(ShopContext);

  // දත්ත ෆිල්ටර් කිරීම
  const filteredProducts = all_product.filter((item) => props.category === item.category);

  return (
    <div className='shop-category'>
      
      {/* 1. බැනර් කොටස */}
      <div className="shopcategory-banner">
        {props.banner ? (
          <img src={props.banner} alt="category-banner" className="shopcategory-banner-img" />
        ) : (
          <p>Banner not found</p>
        )}
      </div>

      {/* 2. නිෂ්පාදන පෙන්වන කොටස */}
      <div className="shopcategory-products">
        {filteredProducts.length > 0 ? (
          filteredProducts.map((item, i) => (
            <Item 
              key={i} 
              id={item.id} 
              name={item.name} 
              image={item.image} 
              new_price={item.new_price} 
              old_price={item.old_price} 
            />
          ))
        ) : (
          <p style={{textAlign: 'center', marginTop: '50px'}}>No products found for this category.</p>
        )}
      </div>
    </div>
  );
};

export default ShopCategory;
